-- table: archive_explicit_gifs
CREATE TABLE `archive_explicit_gifs` (
  `id` int NOT NULL AUTO_INCREMENT,
  `file_name` varchar(512) NOT NULL,
  `perceptual_hash_dhash` varchar(256) DEFAULT NULL,
  `perceptual_hash_phash` varchar(256) DEFAULT NULL,
  `perceptual_hash_average` varchar(256) DEFAULT NULL,
  `perceptual_hash_whash` varchar(256) DEFAULT NULL,
  `md5_hash` varchar(32) DEFAULT NULL,
  `e621_post_id` int DEFAULT NULL,
  `hash_method` varchar(64) DEFAULT 'md5',
  `hash_type` varchar(64) DEFAULT 'perceptual',
  `file_size` bigint DEFAULT NULL,
  `file_modified_at` datetime DEFAULT NULL,
  `file_created_at` datetime DEFAULT NULL,
  `file_path` text NOT NULL,
  `last_artist_check` timestamp NULL DEFAULT NULL,
  `artist_matched` varchar(255) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `unique_file_path` (`file_path`(500)),
  KEY `idx_phash` (`perceptual_hash_phash`(100)),
  KEY `idx_dhash` (`perceptual_hash_dhash`(100)),
  KEY `idx_avg_hash` (`perceptual_hash_average`(100)),
  KEY `idx_whash` (`perceptual_hash_whash`(100)),
  KEY `idx_md5_hash` (`md5_hash`),
  KEY `idx_e621_post_id` (`e621_post_id`),
  KEY `idx_file_name` (`file_name`),
  KEY `idx_hash_method` (`hash_method`),
  KEY `idx_last_artist_check` (`last_artist_check`),
  KEY `idx_artist_matched` (`artist_matched`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

